import { memo, useEffect } from "react";
import { useGLTF } from "@react-three/drei";
// #if DEBUG
import { useControls } from "leva";
// #endif
import { useScene } from "@/lib/contexts/SceneContext";
import { enableShadows } from "@/utils/three";

type PinboardControls = {
    pinboardY: number;
    pinboardZ: number;
    pinboardScale: number;
};

// Generated by .bin/generate-scene-models.mts 1 unit tall, centered on its
// origin with its back on the wall, so `pinboard.scale` is its height
const PINBOARD_MODEL_PATH = "/models/cartoon_pinboard.glb";

const Pinboard = memo(() => {
    const { pinboard } = useScene();
    const pinboardModel = useGLTF(PINBOARD_MODEL_PATH);

    useEffect(() => {
        enableShadows(pinboardModel.scene);
    }, [pinboardModel.scene]);

    let pinboardY: number, pinboardZ: number, pinboardScale: number;

    // #if DEBUG
    ({ pinboardY, pinboardZ, pinboardScale } = useControls(
        "Pinboard",
        {
            pinboardY: {
                value: pinboard?.position?.y ?? 0,
                min: 0,
                max: 10,
                step: 0.01,
            },
            pinboardZ: {
                value: pinboard?.position?.z ?? 0,
                min: -14,
                max: 14,
                step: 0.01,
            },
            pinboardScale: {
                value: pinboard?.scale ?? 1,
                min: 1,
                max: 8,
                step: 0.01,
            },
        },
        { collapsed: true }
    ) as PinboardControls);
    // #endif

    // #if !DEBUG
    pinboardY = pinboard?.position?.y ?? 0;
    pinboardZ = pinboard?.position?.z ?? 0;
    pinboardScale = pinboard?.scale ?? 1;
    // #endif

    return (
        <primitive
            object={pinboardModel.scene}
            position={[pinboard?.position?.x ?? 0, pinboardY, pinboardZ]}
            rotation={[0, pinboard?.rotation?.y ?? 0, 0]}
            scale={[pinboardScale, pinboardScale, pinboardScale]}
        />
    );
});
Pinboard.displayName = "Pinboard";

useGLTF.preload(PINBOARD_MODEL_PATH);

export default Pinboard;
